1	import { useMutation, useQueryClient } from '@tanstack/react-query';
2	import { useState } from 'react';
3	import { postJson, putJson } from '../../api/http';
4	import { ClaimCells } from '../../slots/defs/claimRow';
5	import { usePeople } from '../people/people.slot';
6	import { useUser } from '../session/useSession';
7	import { claimsKey, type Claim, type ClaimStatus } from './useClaims';
8	
9	// `review`: a steward's approve (to SETTLED) or reject (back to OPEN, with a reason) of a PENDING claim.
10	type Change = { status: ClaimStatus; review?: boolean; reason?: string };
11	
12	const ACTIONS: Array<{ action: string; change: Change; label: string }> = [
13	  { action: 'open', change: { status: 'OPEN' }, label: 'Open' },
14	  { action: 'settle', change: { status: 'SETTLED' }, label: 'Settle' },
15	  { action: 'void', change: { status: 'VOID' }, label: 'Void' },
16	  { action: 'approve', change: { status: 'SETTLED', review: true }, label: 'Approve' },
17	];
18	
19	// A claim's number and status, the buttons that open, settle, void, approve or reject it, and a steward's move of a DRAFT,
20	// OPEN or PENDING claim to another person (listed then as that person's newest claim). A change its status does not
21	// allow, a settle or approve by the user who opened the claim, or an approve or reject by a non-steward, is refused by the
22	// server, and the refusal shows on the claim until its next action (only the last action's error shows). A clerk's settle above the clerk limit leaves it PENDING.
23	// A steward may void a SETTLED claim within 7 days of its settlement (not in a closed period): its frozen due still shows but
24	// counts in no total.
25	// An OPEN claim can be deferred to a date after the sheet's today (not in a closed period): until then it counts in no
26	// total, is not overdue and cannot be settled; whether it is deferred, and until when, shows on the claim.
27	// A claim not SETTLED or VOID takes a proof, raising its proofs count by one; one whose due is above the proof threshold
28	// in force on its date cannot be settled or approved while it has none (refused before the clerk limit is considered).
29	// An OPEN claim (not deferred, not in a closed period) can be split: an amount above 0.00 and below its own goes to a new
30	// OPEN claim with the next number, listed as the person's newest and showing the claim's number as split-from.
31	function ClaimStatusCell({ sheetId, claim }: { sheetId: string; user: string; personId: number; claim: Claim }) {
32	  const [user] = useUser();
33	  const queryClient = useQueryClient();
34	  const [reason, setReason] = useState('');
35	  const [moveTo, setMoveTo] = useState('');
36	  const [deferUntil, setDeferUntil] = useState('');
37	  const [splitAmount, setSplitAmount] = useState('');
38	  const people = usePeople(sheetId);
39	  const change = useMutation({
40	    mutationFn: (to: Change) =>
41	      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/status`, { ...to, by: user ?? '' }),
42	    onSuccess: () => {
43	      setReason('');
44	      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
45	    },
46	  });
47	  const reassign = useMutation({
48	    mutationFn: (personId: string) => {
49	      if (personId === '') throw new Error('Choose the person to move the claim to');
50	      return putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/person`,
51	        { personId: Number(personId), by: user ?? '' });
52	    },
53	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
54	  });
55	  // A steward's re-settle of a SETTLED claim at the figure it would have today as an open claim bound by no statement.
56	  const resettle = useMutation({
57	    mutationFn: () =>
58	      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/resettle`, { by: user ?? '' }),
59	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
60	  });
61	  const defer = useMutation({
62	    mutationFn: (until: string) => {
63	      if (until.trim() === '') throw new Error('Enter the date to defer the claim until');
64	      return postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/defer`,
65	        { until: until.trim(), by: user ?? '' });
66	    },
67	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
68	  });
69	  const proof = useMutation({
70	    mutationFn: () =>
71	      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/proof`, { by: user ?? '' }),
72	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
73	  });
74	  const split = useMutation({
75	    mutationFn: (amount: string) =>
76	      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/split`,
77	        { amount: amount.trim(), by: user ?? '' }),
78	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
79	  });
80	  // Each action on the claim clears the other's refusal, so one error shows: the last action's.
81	  const changeTo = (to: Change) => {
82	    reassign.reset();
83	    resettle.reset();
84	    defer.reset();
85	    proof.reset();
86	    split.reset();
87	    change.mutate(to);
88	  };
89	  const busy = change.isPending || reassign.isPending || resettle.isPending || defer.isPending || proof.isPending || split.isPending;
90	  const error = change.error ?? reassign.error ?? resettle.error ?? defer.error ?? proof.error ?? split.error;
91	
92	  return (
93	    <>
94	      <span data-testid="claim-number">{claim.number ?? ''}</span>{' '}
95	      <span data-testid="claim-status">{claim.status}</span>{' '}
96	      <span data-testid="claim-opened-by">{claim.openedBy ?? ''}</span>{' '}
97	      {ACTIONS.map((a) => (
98	        <button
99	          key={a.action}
100	          type="button"
